#!/bin/sh
# Build and install Omni Launcher as a flatpak for the current user.
#
# Prerequisites (the LLVM extension is not optional: Flutter's Linux build
# hard-codes clang, and the base SDK only ships gcc):
#   flatpak install --user flathub org.flatpak.Builder \
#       org.freedesktop.Sdk//26.08 org.freedesktop.Sdk.Extension.llvm22//26.08
#
# For a standalone file instead of an installed app:
#   flatpak build-bundle "$BUILD_DIR/../repo" OmniLauncher-x86_64.flatpak \
#       io.github.PuppyCodingBadly.OmniLauncher
#
# The manifest is generated by flatpak-flutter from flatpak-flutter.yml; see
# README -> Packaging it yourself.
#
# IMPORTANT: the generated manifest pins a `commit:` of the remote repository,
# so this script builds that PINNED commit, NOT your local checkout — local
# changes are ignored unless they were pushed and the manifest was regenerated
# at that commit:
#   flatpak-flutter/flatpak-flutter.py flatpak-flutter.yml
# Cutting a release likewise means regenerating the manifest at the release
# commit, committing that, and tagging the commit that carries it; the manifest
# cannot name its own commit, so the CI workflow only requires the pin to sit in
# the tag's history.
set -eu

SELF=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
BUILD_DIR=${BUILD_DIR:-"$SELF/build-dir"}

flatpak run org.flatpak.Builder \
    --user \
    --install \
    --force-clean \
    --disable-rofiles-fuse \
    "$BUILD_DIR" \
    "$SELF/../io.github.PuppyCodingBadly.OmniLauncher.yml"

echo
echo "Installed. Run it with:"
echo "  flatpak run io.github.PuppyCodingBadly.OmniLauncher"
echo "or from your app grid as \"Omni Launcher (Flutter)\"."
